 [[f.sets,'séries'],[f.minutes,'minutos'],[f.streak,f.streak===1?'semana seguida':'semanas seguidas']].forEach(([value,label],i)=>{const left=60+i*330;x.fillStyle='#151816';box(left,840,300,360,48);x.fillStyle='#f4f6f1';x.font=font(800,140);x.fillText(String(value),left+150,1050);x.fillStyle='#a3aca2';x.font=font(500,30);x.fillText(label,left+150,1125)});
