const openRunner=()=>{if(!$('runnerDialog').open)$('runnerDialog').showModal()};
const pending=()=>{const value=read('cal_active_run',null);return value&&Array.isArray(value.items)&&value.items.length&&value.items.every(i=>byId.has(i.id))?value:null};
function checkpoint(){if(!run)return;const now=Date.now();if(!held)run.elapsed=Math.min(604800000,run.elapsed+Math.max(0,now-openedAt));openedAt=now;write('cal_active_run',run);window.dispatchEvent(new Event('training-updated'))}
