 $('runnerContent').innerHTML=`<section class="run-pre"><p class="set-phase">Pronto para começar</p><h2 id="runnerTitle" class="run-title">${esc(run.name)}</h2><p class="pre-meta">${main.length} exercícios · ${main.reduce((n,i)=>n+i.sets,0)} séries · cerca de ${Math.max(1,Math.round(seconds/60))} min · acabas às ${endAt(seconds)}</p>${gear.length?`<div class="pre-block"><span>Vais precisar de</span><p class="pre-gear">${gear.map(esc).join(' · ')}</p></div>`:''}<div class="pre-block"><span>Tempo</span><div class="pre-chips">${chip('data-minutes="0"','Completo',!setup.minutes)}${options.map(m=>chip(`data-minutes="${m}"`,m+' min',setup.minutes===m)).join('')}</div></div><div class="pre-block"><span>Antes de começar</span><div class="pre-chips">${chip('data-setup="warmup"','Aquecimento de 2 min',!!setup.warmup)}${jumpy?chip('data-setup="quiet"','Sem saltos',!!setup.quiet):''}</div></div>${prefs.checkin?`<div class="pre-block"><span>Quanto dormiste?</span><div class="pre-chips">${[['short','Menos de 6 h'],['ok','6 a 8 h'],['long','Mais de 8 h']].map(([v,l])=>chip(`data-sleep="${v}"`,l,setup.sleep===v)).join('')}</div></div><p class="pre-ask">Como te sentes hoje?</p><div class="pre-feel">${[['Tired','tired','😴','Cansado'],['Ok','ok','🙂','Normal'],['Great','great','💪','Em forma']].map(([id,v,icon,l])=>`<button id="feel${id}" type="button" data-feel="${v}"><b aria-hidden="true">${icon}</b>${l}</button>`).join('')}</div><p class="source-note pre-note">${setup.sleep==='short'?'Dormiste pouco: se não estiveres “Em forma”, a app faz uma versão mais leve.':'Toca numa opção e o treino começa. “Cansado” faz uma versão mais leve.'}</p>`:`<button id="feelOk" type="button" class="primary run-go" data-feel="ok">▶ Começar</button>`}</section>`;
