const cam=!s.warmup&&window.CameraCoach?.supported()&&CameraCoach.kindFor(e),timed=s.unit==='s',step=timed?5:1,planNote=WORKOUT_PLANS.find(p=>p.name===run.name)?.exerciseNotes?.[s.id],weight=run.inputs?.weight??run.lastWeights[s.id]??previous.at(-1)?.weight??0,hint=prefs.tap&&!run.hinted&&Number(local('cal_ui_taphint','0'))<3;
const coach=!tip||(tip.kind!=='harder'&&tip.reps===s.reps)?'':`<div class="coach-tip"><p><strong>Sugestão do treinador</strong>${tip.kind==='increase'?`Da última vez fizeste ${tip.floor} em todas as séries. Hoje tenta ${tip.reps}.`:tip.kind==='ease'?`A última sessão ficou abaixo do objetivo. Hoje faz ${tip.reps} e volta a subir depois.`:tip.kind==='keep'?`Da última vez chegaste a ${tip.reps} com esforço. Mantém esse valor.`:`Já fazes ${tip.floor} em todas as séries. Experimenta uma variante mais difícil em “Mais opções”.`}</p><div class="coach-actions">${tip.kind==='harder'?'':`<button id="acceptTip" class="primary">Usar ${tip.reps}</button>`}<button id="dismissTip" class="text-button">${tip.kind==='harder'?'Entendido':'Agora não'}</button></div></div>`;
